(function(){"use strict";var KEY_FONT="reader:font-size";var KEY_THEME="reader:theme";var MIN=14,MAX=32,STEP=1;function font(){var v=parseInt(localStorage.getItem(KEY_FONT)||"",10);return isNaN(v)?17:Math.min(Math.max(v,MIN),MAX);}
function setFont(v){v=Math.min(Math.max(v,MIN),MAX);document.documentElement.style.setProperty("--reader-font-size",v+"px");localStorage.setItem(KEY_FONT,String(v));var dec=document.getElementById("font-dec");var inc=document.getElementById("font-inc");if(dec)dec.disabled=v<=MIN;if(inc)inc.disabled=v>=MAX;}
function theme(){return localStorage.getItem(KEY_THEME)||(window.matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light");}
function setTheme(t){document.documentElement.classList.toggle("dark",t==="dark");localStorage.setItem(KEY_THEME,t);}
var progressEl=document.getElementById("progress");var hideTimer=null;function showProgress(){if(progressEl)progressEl.classList.add("show");}
function hideProgress(){if(!progressEl)return;if(hideTimer)clearTimeout(hideTimer);hideTimer=setTimeout(function(){progressEl.classList.remove("show");},400);}
function esc(s){return String(s).replace(/[&<>"']/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c];});}
var tocCache={};function getToc(bookId){if(tocCache[bookId])return Promise.resolve(tocCache[bookId]);showProgress();return fetch("/books/"+bookId+"/toc.json").then(function(r){if(!r.ok)throw new Error("HTTP "+r.status);return r.json();}).then(function(d){tocCache[bookId]=d;return d;}).finally(function(){hideProgress();});}
function renderTocTree(toc,currentFile){var html='<div class="toc-book">'+esc(toc.title)+"</div><ul class=\"toc-tree\">";for(var i=0;i<toc.chapters.length;i++){var ch=toc.chapters[i];var cur=ch.file===currentFile;html+='<li class="toc-ch'+(cur?" current":"")+'">';html+='<div class="toc-ch-row">';if(ch.subs.length){html+='<span class="toc-toggle-subs" role="button" tabindex="0" aria-label="展开小节">▸</span>';}else{html+='<span class="toc-toggle-subs toc-toggle-none"></span>';}
html+='<a href="'+ch.file+'">'+esc(ch.title)+"</a></div>";if(ch.subs.length){html+='<ul class="toc-sub-list'+(cur?" open":"")+'">';for(var j=0;j<ch.subs.length;j++){var s=ch.subs[j];html+='<li class="toc-sub level-'+s.level+'"><a href="'+ch.file+"#"+s.id+'">'
+esc(s.title)+"</a></li>";}
html+="</ul>";}
html+="</li>";}
html+="</ul>";return html;}
function initTocSide(){var side=document.getElementById("toc-side");if(!side)return;var bookId=side.getAttribute("data-book-id");var current=side.getAttribute("data-current");var body=document.getElementById("toc-body");var backdrop=document.getElementById("toc-backdrop");var closeBtn=document.getElementById("toc-close");var fab=document.getElementById("toc-fab");var desktop=window.matchMedia("(min-width: 1100px)");function bindToggles(root){var toggles=root.querySelectorAll(".toc-toggle-subs");for(var i=0;i<toggles.length;i++){(function(el){el.addEventListener("click",function(e){e.stopPropagation();el.closest(".toc-ch").classList.toggle("open");});})(toggles[i]);}}
function fill(){getToc(bookId).then(function(toc){body.innerHTML=renderTocTree(toc,current);bindToggles(body);var curRow=body.querySelector(".toc-ch.current");if(curRow)curRow.scrollIntoView({block:"center"});}).catch(function(){body.innerHTML='<p class="toc-loading">目录加载失败</p>';});}
function openMobile(){side.classList.add("open");backdrop.hidden=false;requestAnimationFrame(function(){backdrop.classList.add("show");});}
function closeMobile(){side.classList.remove("open");backdrop.classList.remove("show");setTimeout(function(){backdrop.hidden=true;},250);}
fab.addEventListener("click",openMobile);closeBtn.addEventListener("click",closeMobile);backdrop.addEventListener("click",closeMobile);desktop.addEventListener("change",function(e){if(e.matches)closeMobile();});document.addEventListener("keydown",function(e){if(e.key==="Escape"&&!desktop.matches&&side.classList.contains("open"))closeMobile();});fill();}
function initBookToc(){var tocEl=document.getElementById("book-toc");if(!tocEl)return;var bookId=tocEl.getAttribute("data-book-id");function renderSubs(ch,ul){var html="";for(var j=0;j<ch.subs.length;j++){var s=ch.subs[j];html+='<li class="level-'+s.level+'"><a href="'+ch.file+"#"+s.id+'">'
+esc(s.title)+"</a></li>";}
ul.innerHTML=html;}
function setExpanded(li,on){li.classList.toggle("expanded",on);var ul=li.querySelector(":scope > .toc-subs");if(ul)ul.hidden=!on;}
getToc(bookId).then(function(toc){var byNum={};for(var i=0;i<toc.chapters.length;i++)byNum[toc.chapters[i].num]=toc.chapters[i];var items=tocEl.querySelectorAll(".toc-item");for(var i=0;i<items.length;i++){var li=items[i];var num=parseInt(li.getAttribute("data-ch"),10);var btn=li.querySelector(":scope > .toc-expand");if(!btn)continue;var ul=li.querySelector(":scope > .toc-subs");var ch=byNum[num];if(!ch||!ch.subs.length)continue;renderSubs(ch,ul);(function(li){btn.addEventListener("click",function(){setExpanded(li,!li.classList.contains("expanded"));});})(li);}}).catch(function(){});}
function initSidebarCollapse(){var collapseBtn=document.getElementById("toc-collapse");var reopenBtn=document.getElementById("toc-reopen");if(!collapseBtn||!reopenBtn)return;var desktop=window.matchMedia("(min-width: 1100px)");function setCollapsed(on){document.documentElement.classList.toggle("sidebar-collapsed",on);try{localStorage.setItem("reader:sidebar",on?"collapsed":"");}catch(e){}}
collapseBtn.addEventListener("click",function(){setCollapsed(true);});reopenBtn.addEventListener("click",function(){setCollapsed(false);});if(desktop.matches){try{if(localStorage.getItem("reader:sidebar")==="collapsed")setCollapsed(true);}catch(e){}}}
function initLightbox(){var box=document.getElementById("lightbox");if(!box)return;var main=box.querySelector(".lightbox-main");var imgs=[].slice.call(document.querySelectorAll(".prose img.lightbox-img"));var idx=-1;function show(i){if(!imgs.length||i<0)return;idx=(i+imgs.length)%imgs.length;main.src=imgs[idx].src;main.alt=imgs[idx].alt||"";box.hidden=false;box.classList.add("show");document.body.style.overflow="hidden";}
function hide(){box.classList.remove("show");setTimeout(function(){box.hidden=true;document.body.style.overflow="";},200);}
function nav(d){if(idx>=0)show(idx+d);}
for(var i=0;i<imgs.length;i++){(function(el){el.addEventListener("click",function(e){e.preventDefault();show(imgs.indexOf(el));});})(imgs[i]);}
box.querySelector(".lightbox-close").addEventListener("click",hide);box.querySelector(".lightbox-prev").addEventListener("click",function(){nav(-1);});box.querySelector(".lightbox-next").addEventListener("click",function(){nav(1);});box.addEventListener("click",function(e){if(e.target===box)hide();});document.addEventListener("keydown",function(e){if(box.hidden)return;if(e.key==="Escape")hide();else if(e.key==="ArrowLeft")nav(-1);else if(e.key==="ArrowRight")nav(1);});}
var BM_KEY="reader:bookmarks";function getBookmarks(){try{return JSON.parse(localStorage.getItem(BM_KEY)||"[]")||[];}
catch(e){return[];}}
function saveBookmarks(bms){try{localStorage.setItem(BM_KEY,JSON.stringify(bms));}catch(e){}}
function bmKey(b){return b.book+"|"+b.chapter;}
function initBookmarks(){var btn=document.getElementById("bookmark-toggle");var listEl=document.getElementById("bookmark-list");if(!btn||!listEl)return;var side=document.getElementById("toc-side");var bookId=side.getAttribute("data-book-id");var chapterFile=side.getAttribute("data-current");var bookTitle=side.getAttribute("data-book-title")||bookId;var chapterTitleEl=document.querySelector(".chapter-title");var chapterTitle=chapterTitleEl?chapterTitleEl.textContent.trim():chapterFile;function currentIndex(bms){for(var i=0;i<bms.length;i++){if(bms[i].book===bookId&&bms[i].chapter===chapterFile)return i;}
return-1;}
function readPos(){var h=document.documentElement.scrollHeight-window.innerHeight;return h>0?window.scrollY/h:0;}
function refresh(){var bms=getBookmarks();btn.classList.toggle("active",currentIndex(bms)>=0);btn.textContent=currentIndex(bms)>=0?"★":"☆";btn.setAttribute("aria-label",currentIndex(bms)>=0?"移除书签":"添加书签");btn.title=currentIndex(bms)>=0?"移除书签":"添加书签";var html='<div class="bm-head">我的书签</div>';if(!bms.length){html+='<p class="bm-empty">暂无书签（侧栏 ☆ 可添加）</p>';}else{html+='<ul class="bm-list">';for(var i=0;i<bms.length;i++){var b=bms[i];var cur=b.book===bookId&&b.chapter===chapterFile;html+='<li class="bm-item'+(cur?" current-book":"")+'">'
+'<a class="bm-link" href="/books/'+b.book+"/"+b.chapter+"?bm="+encodeURIComponent(bmKey(b))+'">'
+'<span class="bm-book">'+esc(b.book_title||b.book)+"</span>"
+'<span class="bm-chapter">'+esc(b.chapter_title||b.chapter)+"</span>"
+'<span class="bm-pos">定位 '+Math.round((b.pos||0)*100)+"%</span></a>"
+'<button class="bm-del" type="button" data-key="'+encodeURIComponent(bmKey(b))+'" aria-label="删除书签">×</button>'
+"</li>";}
html+="</ul>";}
listEl.innerHTML=html;var dels=listEl.querySelectorAll(".bm-del");for(var j=0;j<dels.length;j++){(function(el){el.addEventListener("click",function(){var key=decodeURIComponent(el.getAttribute("data-key"));var arr=getBookmarks().filter(function(x){return bmKey(x)!==key;});saveBookmarks(arr);refresh();});})(dels[j]);}}
btn.addEventListener("click",function(){var bms=getBookmarks();var i=currentIndex(bms);if(i>=0){bms.splice(i,1);}else{bms.push({book:bookId,book_title:bookTitle,chapter:chapterFile,chapter_title:chapterTitle,pos:readPos(),addedAt:Date.now(),});}
saveBookmarks(bms);refresh();});refresh();}
function restoreBookmark(){var m=location.search.match(/[?&]bm=([^&]+)/);if(!m)return;var key=decodeURIComponent(m[1]);var b=null;var bms=getBookmarks();for(var i=0;i<bms.length;i++){if(bmKey(bms[i])===key){b=bms[i];break;}}
if(!b)return;function go(){var h=document.documentElement.scrollHeight-window.innerHeight;window.scrollTo(0,h>0?(b.pos||0)*h:0);}
if(document.readyState==="complete")setTimeout(go,60);else window.addEventListener("load",function(){setTimeout(go,60);});}
function initBackTop(){var btn=document.getElementById("back-top");if(!btn)return;function toggle(){btn.hidden=window.scrollY<600;}
toggle();window.addEventListener("scroll",toggle,{passive:true});btn.addEventListener("click",function(){window.scrollTo({top:0,behavior:"smooth"});});}
function init(){setFont(font());setTheme(theme());var dec=document.getElementById("font-dec");var inc=document.getElementById("font-inc");var tg=document.getElementById("theme-toggle");if(dec)dec.addEventListener("click",function(){setFont(font()-STEP);});if(inc)inc.addEventListener("click",function(){setFont(font()+STEP);});if(tg)tg.addEventListener("click",function(){setTheme(theme()==="dark"?"light":"dark");});initTocSide();initBookToc();initSidebarCollapse();initBookmarks();restoreBookmark();initLightbox();initBackTop();}
if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init);}else{init();}})();